{"command": "cd /tmp/golden && python3 - <<'PY'
import sqlite3, os
for n in ('a','b','c'):
    p=f'/tmp/golden/{n}.db'
    print('='*60)
    print(n, os.path.getsize(p))
    try:
        con=sqlite3.connect(f'file:{p}?mode=ro',uri=True)
        print('schema:', con.execute("select type,name,sql from sqlite_master").fetchall())
        try:
            print('count:', con.execute("select count(*) from cities").fetchone())
            print('sample:', con.execute("select * from cities limit 5").fetchall())
        except Exception as e:
            print('query err:', e)
        try:
            print('integrity:', con.execute("pragma integrity_check").fetchall()[:5])
        except Exception as e:
            print('integrity err:', e)
        con.close()
    except Exception as e:
        print('open err:', e)
PY", "description": "Inspect each candidate database with sqlite3"}

